// FineTune/Audio/Dynamics/KEMARHRTF.swift
//
// Head-related impulse responses measured on a KEMAR dummy head (DB-4004 small pinna),
// elevation 0°, from the MIT Media Lab "compact" data set.
//
//   HRTF measurements of a KEMAR dummy-head microphone
//   Bill Gardner and Keith Martin, MIT Media Lab Machine Listening Group, 1994.
//   https://sound.media.mit.edu/resources/KEMAR.html
//
//   "This data is Copyright 1994 by the MIT Media Laboratory. It is provided free with no
//    restrictions on use, provided the authors are cited when the data is used in any research
//    or commercial application."
//
// Layout: for each azimuth 0°...120° in 5° steps, 128 Float32 taps at 44.1 kHz for the ear on the
// source's side (ipsilateral) followed by 128 taps for the far ear (contralateral). A source at a
// positive azimuth is to the listener's right; the left-hand mirror image uses the same pair swapped.

import Foundation

nonisolated enum KEMARHRTF {
    static let sampleRate: Double = 44_100
    static let tapCount = 128
    static let azimuths: [Int] = Array(stride(from: 0, through: 120, by: 5))

    /// Nearest measured azimuth (5° grid) for an arbitrary angle in degrees.
    static func nearestAzimuth(to degrees: Double) -> Int {
        let clamped = min(max(degrees, 0), 120)
        return Int((clamped / 5).rounded()) * 5
    }

    /// Ipsilateral and contralateral impulse responses (44.1 kHz) for the source at `azimuth`.
    static func hrir(azimuth: Int) -> (ipsi: [Float], contra: [Float]) {
        guard let index = azimuths.firstIndex(of: azimuth) else { return hrir(azimuth: nearestAzimuth(to: Double(azimuth))) }
        let base = index * tapCount * 2
        return (Array(samples[base..<base + tapCount]), Array(samples[base + tapCount..<base + tapCount * 2]))
    }

    private static let samples: [Float] = {
        guard let data = Data(base64Encoded: encoded) else { return [] }
        return data.withUnsafeBytes { raw in
            Array(raw.bindMemory(to: Float.self))
        }
    }()

